                                (b6 << 22) | (b7 << 16);
                res1 = be64_to_cpu(res1);
                *(uint64_t *)o = res1;
                c += 8;
                o += 6;
                outl += 6;
                srclen -= 8;
            }
            if (srclen-- == 0) {
                ret = 1;
                break;
            }
            if ((q = base64_table_dec[*c++]) >= 254) {
                st.eof = BASE64_EOF;
                break;
            }
            st.carry = q << 2;
            st.bytes++;
        case 1:
            if (srclen-- == 0) {
                ret = 1;
                break;
            }
            if ((q = base64_table_dec[*c++]) >= 254) {
                st.eof = BASE64_EOF;
                break;
            }
            *o++ = st.carry | (q >> 4);
            st.carry = q << 4;
            st.bytes++;
            outl++;
        case 2:
            if (srclen-- == 0) {
                ret = 1;
                break;
            }
            if ((q = base64_table_dec[*c++]) >= 254) {
                st.bytes++;
                if (q == 254) {
                    if (srclen-- != 0) {
                        st.bytes = 0;
                        st.eof = BASE64_EOF;
                        q = base64_table_dec[*c++];
                        ret = ((q == 254) && (srclen == 0)) ? 1 : 0;
