	*(uint64_t *)(o + 12) = be64_to_cpu(res2);
	*(uint64_t *)(o + 18) = be64_to_cpu(res3);
	*(uint64_t *)(o + 24) = be64_to_cpu(res4);
	*(uint64_t *)(o + 30) = be64_to_cpu(res5);
	*(uint64_t *)(o + 36) = be64_to_cpu(res6);
	*(uint64_t *)(o + 42) = be64_to_cpu(res7);

